// Divide o texto extraído do PDF em lotes menores por unidade, para:
// 1) nunca estourar o limite de tokens de saída do modelo (o que causava
//    truncamento e perda de dados, ex. e-mails, em PDFs grandes/atípicos);
// 2) permitir reprocessar um lote específico no futuro, se necessário.
//
// Ajuste UNIDADES_POR_LOTE se quiser lotes maiores (mais rápido, mais risco
// de corte) ou menores (mais chamadas de IA, mais seguro).
const UNIDADES_POR_LOTE = 15;

const textoCompleto = $('Extrai o texto do PDF1').first().json.extractedText || '';
const resolvedModel = $json.resolvedModel;

// Quebra o texto sempre antes de uma ocorrência de "Unidade:" seguida de
// dígito, que é o marcador de início de registro nos dois formatos de
// documento que já vimos (lista simples e relatório em colunas).
const blocos = textoCompleto
  .split(/(?=Unidade:\s*\S)/g)
  .map((b) => b.trim())
  .filter((b) => b.length > 0);

// Fallback: se não encontrarmos nenhum marcador "Unidade:" (documento em
// formato totalmente diferente), processa o texto inteiro em um único lote
// em vez de falhar.
const unidades = blocos.length > 0 ? blocos : [textoCompleto];

const lotes = [];
for (let i = 0; i < unidades.length; i += UNIDADES_POR_LOTE) {
  lotes.push(unidades.slice(i, i + UNIDADES_POR_LOTE).join('\n\n'));
}

return lotes.map((textoLote, idx) => ({
  json: {
    resolvedModel,
    batchIndex: idx,
    totalBatches: lotes.length,
    textoLote,
  },
}));

// Consolida os "output" de todos os lotes processados pela IA em um único
// array "rows", antes de enviar para o callback do SaaS.
const todasAsLinhas = [];

for (const item of $input.all()) {
  const linhasDoLote = item.json.output || [];
  todasAsLinhas.push(...linhasDoLote);
}

return [{ json: { rows: todasAsLinhas } }];

